"use client";

import React from "react";
import CopyButton from "./CopyButton";

interface AIModel {
  _id: string;
  modelId: string;
  displayName: string;
}

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  modelId?: string;
}

interface AnswerDisplayProps {
  messages: Message[];
  isLoading: boolean;
  selectedModels: AIModel[];
  error: string | null;
}

const bubbleBase =
  "relative w-fit max-w-[min(80ch,calc(100%-56px))] rounded-2xl px-4 py-3 shadow-md whitespace-pre-wrap break-words";

const roleStyles = {
  user: "bg-[#E8F1F5] text-gray-900 rounded-br-md",
  assistant: "bg-white/85 text-gray-900 border border-black/5 rounded-bl-md",
};

export default function AnswerDisplay({
  messages,
  isLoading,
  selectedModels,
  error,
}: AnswerDisplayProps) {
  // map modelId -> displayName để gắn nhãn model
  const modelNameById = React.useMemo(() => {
    const m = new Map<string, string>();
    selectedModels.forEach((x) => m.set(x.modelId, x.displayName || x.modelId));
    return m;
  }, [selectedModels]);

  return (
    <div className="flex flex-col gap-3">
      {error && (
        <div className="text-red-700 bg-red-50 border border-red-200 rounded-lg px-4 py-3">
          {error}
        </div>
      )}

      {messages.map((m) => {
        const isAssistant = m.role === "assistant";
        const align = isAssistant ? "items-start" : "items-end";
        const rowJustify = isAssistant ? "justify-start" : "justify-end";
        const bubbleClass = `${bubbleBase} ${isAssistant ? roleStyles.assistant : roleStyles.user}`;

        const modelBadge =
          isAssistant && m.modelId ? modelNameById.get(m.modelId) ?? m.modelId : null;

        return (
          <div key={m.id} className={`flex ${rowJustify}`}>
            <div className={`flex ${align} gap-2 max-w-full`}>
              {/* avatar tròn nhỏ */}
              <div
                className={
                  "h-8 w-8 shrink-0 rounded-full grid place-items-center text-xs font-semibold " +
                  (isAssistant ? "bg-indigo-500/90 text-white" : "bg-emerald-500/90 text-white")
                }
                aria-hidden="true"
              >
                {isAssistant ? "AI" : "You"}
              </div>

              <div className="flex flex-col gap-1">
                {/* Hàng tiêu đề: badge model + nút copy */}
                <div className="flex items-center gap-2 px-1">
                  {modelBadge && (
                    <span className="text-[10px] uppercase tracking-wide rounded-md bg-black/5 px-1.5 py-0.5 text-gray-700 border border-black/10">
                      {modelBadge}
                    </span>
                  )}

                  {/* Chỉ hiển thị nút copy cho assistant (nhưng bạn có thể bật cho user nếu muốn) */}
                  {isAssistant && (
                    <CopyButton
                      text={m.content}
                      className="ml-auto"
                      label="Sao chép nội dung phản hồi"
                    />
                  )}
                </div>

                {/* bubble nội dung */}
                <div className={bubbleClass}>
                  {m.content}
                  {/* nút copy nổi ở góc phải trên bubble (desktop) */}
                  {isAssistant && (
                    <div className="hidden md:block absolute -top-3 -right-3">
                      <CopyButton text={m.content} label="Sao chép" />
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        );
      })}

      {isLoading && (
        <div className="flex items-center gap-2 text-gray-600">
          <span className="h-2 w-2 rounded-full bg-gray-500 animate-pulse"></span>
          <span>Đang lấy câu trả lời…</span>
        </div>
      )}
    </div>
  );
}
